-- Tenant migration 0024: what a workshop's EMAIL REPLY may do (ADR-033). Idempotent.
-- Workshops never sign up. When one replies to the autogenerated email with its estimate or invoice attached, the app files the message on the job
-- card and tells the people who handle it; staff then enter the figures. The inbound route runs as role inbound_mail: no table access, only EXECUTE on
-- the three functions below, SECURITY DEFINER with a pinned search_path, so a bug in the route cannot read or change anything else.

create table if not exists workshop_emails (
  id             uuid primary key default gen_random_uuid(),
  job_card_id    uuid not null references job_cards(id) on delete cascade,
  vendor_id      uuid not null references vendors(id),
  kind           text not null check (kind in ('quotation', 'invoice')),
  from_address   text not null,
  sender_matches boolean not null,            -- the sender is the address the organization entered for this workshop
  subject        text,
  body_text      text,
  message_id     text,
  file_count     int not null default 0,
  status         text not null default 'new' check (status in ('new', 'entered', 'dismissed')),
  handled_by     uuid,
  handled_at     timestamptz,
  received_at    timestamptz not null default now()
);
-- Which email a file came with, so the AI (and staff) read the right files for the right reply (ADR-034).
alter table attachments add column if not exists source_email_id uuid;

create unique index if not exists workshop_emails_message_idx on workshop_emails(message_id) where message_id is not null;
create index if not exists workshop_emails_job_idx on workshop_emails(job_card_id);

-- Who handled a workshop's reply, and what was filed, can always be traced to a person (or to the mail service when there is none).
drop trigger if exists workshop_emails_audit on workshop_emails;
create trigger workshop_emails_audit after insert or update or delete on workshop_emails for each row execute function audit_trigger();

do $$
begin
  if not exists (select 1 from pg_roles where rolname = 'inbound_mail') then
    create role inbound_mail nologin noinherit;
  end if;
  execute format('grant inbound_mail to %I', current_user);   -- lets the app's own login switch to it with SET ROLE
end $$;

do $mig$
declare s text := current_schema();
begin
  -- Whether the reply still has somewhere to land: the job card is this workshop's and has not moved past what the reply is for.
  execute format($f$
    create or replace function inbound_target(p_job uuid, p_vendor uuid, p_kind text)
    returns table (job_no text, vendor_name text, vendor_email text)
    language sql stable security definer set search_path = %1$I, public as $b$
      select jc.job_no, vn.name, vn.email
        from job_cards jc join vendors vn on vn.id = jc.vendor_id
       where jc.id = p_job and jc.vendor_id = p_vendor and vn.status = 'active'
         and ((p_kind = 'quotation' and jc.status in ('vendor_assigned', 'quotation_received'))
           or (p_kind = 'invoice'   and jc.status in ('quotation_approved', 'in_progress', 'completed', 'invoiced')))
    $b$
  $f$, s);

  -- Has this message been filed already? Asked before any file is downloaded, so a repeated delivery saves nothing twice.
  execute format($f$
    create or replace function workshop_email_seen(p_message_id text) returns boolean
    language sql stable security definer set search_path = %1$I, public as $b$
      select exists (select 1 from workshop_emails where message_id = p_message_id)
    $b$
  $f$, s);

  -- Files one message. Idempotent on the message id, because the mail service delivers a webhook more than once when it is slow to hear back.
  -- The people who decide on estimates, or check invoices, are told.
  execute format($f$
    create or replace function file_workshop_email(p_job uuid, p_vendor uuid, p_kind text, p_from text, p_subject text, p_body text, p_message_id text)
    returns uuid language plpgsql security definer set search_path = %1$I, public as $b$
    declare jc job_cards; vn vendors; eid uuid; perm text := case when p_kind = 'quotation' then 'quotation.approve' else 'invoice.verify' end;
    begin
      if p_kind not in ('quotation', 'invoice') then raise exception 'unknown kind'; end if;
      select * into jc from job_cards where id = p_job;
      select * into vn from vendors where id = p_vendor;
      if jc.id is null or vn.id is null or jc.vendor_id is distinct from p_vendor then raise exception 'reply is not valid'; end if;
      if p_message_id is not null then
        select id into eid from workshop_emails where message_id = p_message_id;
        if eid is not null then return eid; end if;
      end if;
      insert into workshop_emails(job_card_id, vendor_id, kind, from_address, sender_matches, subject, body_text, message_id)
      values (p_job, p_vendor, p_kind, left(p_from, 320), lower(trim(coalesce(vn.email, ''))) = lower(trim(p_from)),
              left(p_subject, 300), left(p_body, 20000), left(p_message_id, 400))
      returning id into eid;
      insert into notifications(user_id, kind, payload)
        select distinct m.user_id, 'workshop.email', jsonb_build_object('job_card_id', p_job, 'job_no', jc.job_no, 'kind', p_kind)
          from public.tenant_memberships m
         where m.tenant_id = (select t.id from public.tenants t where t.schema_name = current_schema()) and m.status = 'active'
           and m.role in (select role_key from role_permissions where permission_key = perm);
      return eid;
    end $b$
  $f$, s);

  -- Records one file that came with a message. It is shown among the job card's files, so it is where staff already look.
  execute format($f$
    create or replace function add_workshop_email_file(p_email uuid, p_path text, p_name text, p_mime text)
    returns void language plpgsql security definer set search_path = %1$I, public as $b$
    declare e workshop_emails;
    begin
      select * into e from workshop_emails where id = p_email for update;
      if e.id is null then raise exception 'email not found'; end if;
      if left(p_path, length(current_schema()) + 1) <> current_schema() || '/' then raise exception 'path outside this workspace'; end if;
      if (select count(*) from attachments where entity_type = 'job_card' and entity_id = e.job_card_id) >= 12 then raise exception 'too many files'; end if;   -- the limit a person adding files has
      insert into attachments(entity_type, entity_id, storage_path, file_name, mime_type, uploaded_by, source_email_id)
      values ('job_card', e.job_card_id, p_path, left(p_name, 200), p_mime, null, p_email);
      update workshop_emails set file_count = file_count + 1 where id = p_email;
    end $b$
  $f$, s);

  execute format('revoke all on function %I.workshop_email_seen(text) from public', s);
  execute format('revoke all on function %I.inbound_target(uuid, uuid, text) from public', s);
  execute format('revoke all on function %I.file_workshop_email(uuid, uuid, text, text, text, text, text) from public', s);
  execute format('revoke all on function %I.add_workshop_email_file(uuid, text, text, text) from public', s);
  execute format('grant usage on schema %I to inbound_mail', s);
  execute format('grant execute on function %I.inbound_target(uuid, uuid, text), %I.file_workshop_email(uuid, uuid, text, text, text, text, text), %I.add_workshop_email_file(uuid, text, text, text) to inbound_mail', s, s, s);
  execute format('grant execute on function %I.workshop_email_seen(text) to inbound_mail', s);
end $mig$;
